import React, { useState } from "react";
import "./ClientsList.css";

// DATA SIMULADA (puedes agregar fechas después)
export const Clients = [
  { title: "Cliente 1", date: "2026-06-01" },
  { title: "Cliente 2", date: "2026-06-05" },
  { title: "Cliente 3", date: "2026-06-10" },
];

const ClientsList = () => {
  const [list, setList] = useState(Clients);

  const [filters, setFilters] = useState({
    query: "",
    dateFrom: "",
    dateTo: "",
    compare: "",
  });

  const [showFilters, setShowFilters] = useState(false);

  // 🔍 FUNCIÓN CENTRAL DE FILTROS
  const applyFilters = (newFilters) => {
    let results = Clients;

    // filtro por texto
    if (newFilters.query) {
      results = results.filter((c) =>
        c.title.toLowerCase().includes(newFilters.query)
      );
    }

    // filtro por fechas
    if (newFilters.dateFrom && newFilters.dateTo) {
      results = results.filter((c) => {
        const date = new Date(c.date);
        return (
          date >= new Date(newFilters.dateFrom) &&
          date <= new Date(newFilters.dateTo)
        );
      });
    }

    // filtro comparar (ejemplo simple)
    if (newFilters.compare === "asc") {
      results = [...results].sort((a, b) =>
        a.title.localeCompare(b.title)
      );
    }

    if (newFilters.compare === "desc") {
      results = [...results].sort((a, b) =>
        b.title.localeCompare(a.title)
      );
    }

    setList(results);
  };

  // 🔎 BUSCADOR
  const handleSearchChange = (e) => {
    const value = e.target.value.toLowerCase();

    const newFilters = {
      ...filters,
      query: value,
    };

    setFilters(newFilters);
    applyFilters(newFilters);
  };

  // 📅 FECHAS
  const handleDateChange = (field, value) => {
    const newFilters = {
      ...filters,
      [field]: value,
    };

    setFilters(newFilters);
    applyFilters(newFilters);
  };

  // 🔽 COMPARAR
  const handleCompareChange = (e) => {
    const value = e.target.value;

    const newFilters = {
      ...filters,
      compare: value,
    };

    setFilters(newFilters);
    applyFilters(newFilters);
  };

  return (
    <div className="container">
      <h2>Clientes</h2>

      {/* 🔍 BUSCADOR */}
      <input
        type="text"
        placeholder="Buscar un cliente..."
        value={filters.query}
        onChange={handleSearchChange}
        className="search"
      />

      {/* BOTÓN FILTRO */}
      <button onClick={() => setShowFilters(!showFilters)}>
        Filtros
      </button>

      {/* PANEL FILTROS */}
      {showFilters && (
        <div className="filters-panel">
          <div>
            <label>Rango de fechas:</label>
            <input
              type="date"
              onChange={(e) =>
                handleDateChange("dateFrom", e.target.value)
              }
            />
            <input
              type="date"
              onChange={(e) =>
                handleDateChange("dateTo", e.target.value)
              }
            />
          </div>

          <div>
            <label>Comparar con:</label>
            <select onChange={handleCompareChange}>
              <option value="">Sin elegir</option>
              <option value="asc">Orden A-Z</option>
              <option value="desc">Orden Z-A</option>
            </select>
          </div>
        </div>
      )}

      {/* LISTA */}
      <div className="list">
        {list.map((client, index) => (
          <div className="card" key={index}>
            <h3>{client.title}</h3>
            <p>{client.date}</p>
          </div>
        ))}

        {list.length === 0 && (
          <p>No hay clientes para mostrar</p>
        )}
      </div>
    </div>
  );
};

export default ClientsList;
